// map.js - OpenLayers setup and map-specific interactions
// Assuming 'ol' is globally available or will be imported

// --- Constants ---
export const TILE_SELECTION_ZOOM = 21;
export const GRID_VISIBILITY_MIN_ZOOM = 16;

// --- Layer Definitions ---
const osmLayer = new ol.layer.Tile({ source: new ol.source.OSM(), visible: false, title: 'osm' });
const satelliteLayer = new ol.layer.Tile({
    source: new ol.source.XYZ({ url: 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', attributions: 'Tiles © ArcGIS', maxZoom: 19 }),
    visible: true, title: 'satellite'
});
const topoLayer = new ol.layer.Tile({
    source: new ol.source.XYZ({ url: 'https://{a-c}.tile.opentopomap.org/{z}/{x}/{y}.png', attributions: 'Map data © OSM contributors, SRTM | Map style © OpenTopoMap (CC-BY-SA)', maxZoom: 17 }),
    visible: false, title: 'topo'
});
export const baseLayers = [osmLayer, satelliteLayer, topoLayer]; // Export for base layer switcher UI

const selectionStyle = new ol.style.Style({ fill: new ol.style.Fill({ color: 'rgba(200, 200, 200, 0.5)' }) });
export const selectionSource = new ol.source.Vector(); // Export for selection logic
const selectionLayer = new ol.layer.Vector({ source: selectionSource, style: selectionStyle, title: 'selection', zIndex: 3 });

const highlightStyle = new ol.style.Style({
    stroke: new ol.style.Stroke({ color: 'rgba(255, 255, 0, 0.8)', width: 4 }),
    fill: new ol.style.Fill({ color: 'rgba(255, 255, 0, 0.2)' }),
    zIndex: 4
});
export const highlightSource = new ol.source.Vector(); // Export for highlight logic
const highlightLayer = new ol.layer.Vector({
    source: highlightSource,
    style: highlightStyle,
    title: 'highlight'
});

const gridStyleZ21 = new ol.style.Style({ stroke: new ol.style.Stroke({ color: 'rgba(0, 0, 0, 1)', width: 1 }) });
export const gridSourceZ21 = new ol.source.Vector(); // Export for grid update logic
const gridLayerZ21 = new ol.layer.Vector({ source: gridSourceZ21, style: gridStyleZ21, title: 'grid-z21', visible: false, zIndex: 1 });
export const selectionTileGrid = ol.tilegrid.createXYZ({ maxZoom: TILE_SELECTION_ZOOM }); // Export if needed elsewhere

// --- Initial User Layer Setup ---
const layer0Id = 'layer-0';
const layer0Name = 'Layer 0';
export const layer0Source = new ol.source.Vector(); // Export if needed directly
const tilesetFeatureStyle = new ol.style.Style({
    stroke: new ol.style.Stroke({ color: 'rgba(0, 128, 128, 0.9)', width: 3 }),
});
export const layer0Layer = new ol.layer.Vector({ // Export initial layer
    source: layer0Source,
    style: tilesetFeatureStyle,
    title: layer0Id,
    zIndex: 2,
    visible: true
});
layer0Layer.set('userLayerName', layer0Name);

// This userLayers object might be better managed in state.js, but let's keep it here for now as per original structure
export const userLayers = { // Export for layer management logic
   [layer0Id]: { name: layer0Name, layer: layer0Layer, ogLayer: null, tilesetCount: 0 }
};

// --- Map Instance ---
let mapInstance = null; // Use let for the instance

export function initializeMap(targetElementId = 'map') {
    if (mapInstance) {
        console.warn("Map already initialized.");
        return mapInstance;
    }

    mapInstance = new ol.Map({
        target: targetElementId,
        layers: [ ...baseLayers, layer0Layer, gridLayerZ21, selectionLayer, highlightLayer ],
        view: new ol.View({ center: ol.proj.fromLonLat([166.52424, -11.26175]), zoom: 12, maxZoom: TILE_SELECTION_ZOOM + 1, minZoom: 0 }), // Centered on Utupua Island
        controls: [],
    });

    console.log("OpenLayers Map Initialized");
    return mapInstance;
}

// Export the map instance getter
export function getMap() {
    if (!mapInstance) {
        console.error("Map accessed before initialization!");
    }
    return mapInstance;
}

// Export other potentially needed items
export const mapElement = document.getElementById('map'); // Keep reference if needed

// Export the initial selected layer value (might move to state.js later)
export let previouslySelectedLayerValue = 'satellite';

// Function to update the selected layer value (needed if moved from main.js)
export function setPreviouslySelectedLayerValue(value) {
    previouslySelectedLayerValue = value;
}
